GO

CREATE PROCEDURE SP_Cita_Delete @IdCita INT
AS BEGIN
  DELETE FROM Cita WHERE IdCita = @IdCita;
END;
GO

CREATE PROCEDURE SP_Cita_GetAll
AS BEGIN
  SELECT ci.IdCita, CONVERT(VARCHAR(10), ci.Fecha, 23) AS Fecha, CONVERT(VARCHAR(5), ci.Hora, 108) AS Hora,
         ci.Estado, ci.Notas, ci.Contacto, ci.Telefono,
         ci.IdCliente, ci.IdUsuario, ci.IdPropiedad, ci.IdConsulta,
         p.Barrio, p.Calle, p.Numeracion,
         LTRIM(RTRIM(ISNULL(cl.Nombre, '') + ' ' + ISNULL(cl.Apellido, ''))) AS ClienteNombre,
         cl.Telefono AS ClienteTelefono,
         u.NombreUsuario AS Agente
  FROM Cita ci
  LEFT JOIN Propiedad p ON p.IdPropiedad = ci.IdPropiedad
  LEFT JOIN Cliente  cl ON cl.IdCliente = ci.IdCliente
  LEFT JOIN Usuario  u  ON u.IdUsuario  = ci.IdUsuario
  ORDER BY ci.Fecha, ci.Hora;
END;
GO

CREATE PROCEDURE SP_Cita_GetId @IdCita INT
AS BEGIN
  SELECT IdCita, CONVERT(VARCHAR(10), Fecha, 23) AS Fecha, CONVERT(VARCHAR(5), Hora, 108) AS Hora,
         Estado, Notas, Contacto, Telefono, IdCliente, IdUsuario, IdPropiedad, IdConsulta
  FROM Cita WHERE IdCita = @IdCita;
END;
GO

CREATE PROCEDURE SP_Cita_Insert
  @Fecha DATE, @Hora TIME = NULL, @Estado NVARCHAR(20) = 'Pendiente', @Notas NVARCHAR(500) = NULL,
  @Contacto NVARCHAR(150) = NULL, @Telefono NVARCHAR(30) = NULL,
  @IdCliente INT = NULL, @IdUsuario INT = NULL, @IdPropiedad INT = NULL, @IdConsulta INT = NULL
AS BEGIN
  VALUES (@Fecha, @Hora, ISNULL(@Estado, 'Pendiente'), @Notas, @Contacto, @Telefono, @IdCliente, @IdUsuario, @IdPropiedad, @IdConsulta);
  SELECT CAST(SCOPE_IDENTITY() AS INT) AS IdCita;
END;
GO

CREATE PROCEDURE SP_Cita_Update
  @IdCita INT, @Fecha DATE, @Hora TIME = NULL, @Estado NVARCHAR(20) = 'Pendiente', @Notas NVARCHAR(500) = NULL,
  @Contacto NVARCHAR(150) = NULL, @Telefono NVARCHAR(30) = NULL,
  @IdCliente INT = NULL, @IdUsuario INT = NULL, @IdPropiedad INT = NULL, @IdConsulta INT = NULL
AS BEGIN
  UPDATE Cita SET Fecha = @Fecha, Hora = @Hora, Estado = ISNULL(@Estado, 'Pendiente'), Notas = @Notas,
         Contacto = @Contacto, Telefono = @Telefono, IdCliente = @IdCliente, IdUsuario = @IdUsuario,
         IdPropiedad = @IdPropiedad, IdConsulta = @IdConsulta
  WHERE IdCita = @IdCita;
END;
GO

