BEGIN UPDATE Operacion SET Tipo=@Tipo,Fecha=@Fecha,IdCliente=@IdCliente,IdPropiedad=@IdPropiedad,IdUsuario=@IdUsuario WHERE IdOperacion=@IdOperacion; END;
