CREATE PROCEDURE SP_Usuario_GetAll AS
BEGIN SELECT u.IdUsuario,u.NombreUsuario,u.Nombre,u.Email,u.Telefono,r.Nombre AS Rol,u.IdRol FROM Usuario u INNER JOIN Rol r ON u.IdRol=r.IdRol; END;
GO

CREATE PROCEDURE SP_Usuario_GetId @IdUsuario INT AS
BEGIN SELECT u.IdUsuario,u.NombreUsuario,u.Nombre,u.Email,u.Telefono,r.Nombre AS Rol,u.IdRol FROM Usuario u INNER JOIN Rol r ON u.IdRol=r.IdRol WHERE u.IdUsuario=@IdUsuario; END;
GO

CREATE PROCEDURE SP_Usuario_Insert
    @NombreUsuario NVARCHAR(100)=NULL,@Nombre NVARCHAR(100),@Email NVARCHAR(100),
    @Telefono NVARCHAR(20)=NULL,@Contrasena NVARCHAR(100),@IdRol INT
AS BEGIN
    IF EXISTS(SELECT 1 FROM Usuario WHERE Email=@Email) BEGIN RAISERROR('EMAIL_DUPLICADO',16,1); RETURN; END
    VALUES(ISNULL(@NombreUsuario,@Nombre),@Nombre,@Email,@Telefono,
           CONVERT(NVARCHAR(256),HASHBYTES('SHA2_256',CAST(@Contrasena AS NVARCHAR(100))),2),@IdRol);
END;
GO

CREATE PROCEDURE SP_Usuario_Login @Nombre NVARCHAR(100),@Contrasena NVARCHAR(100) AS
BEGIN
    DECLARE @Hash NVARCHAR(256);
    SET @Hash=CONVERT(NVARCHAR(256),HASHBYTES('SHA2_256',CAST(@Contrasena AS NVARCHAR(100))),2);
    SELECT u.IdUsuario,u.NombreUsuario,u.Nombre,u.Email,r.Nombre AS Rol
    FROM Usuario u INNER JOIN Rol r ON u.IdRol=r.IdRol
    WHERE (u.Nombre=@Nombre OR u.NombreUsuario=@Nombre) AND u.Contrasena=@Hash;
END;
GO

CREATE PROCEDURE SP_Usuario_Update
    @IdUsuario INT,@Nombre NVARCHAR(100),@Email NVARCHAR(100),
    @Contrasena NVARCHAR(256)=NULL,@IdRol INT
AS BEGIN
    IF @Contrasena IS NULL OR @Contrasena='' OR @Contrasena='___NOCHANGE___'
        UPDATE Usuario SET Nombre=@Nombre,Email=@Email,IdRol=@IdRol WHERE IdUsuario=@IdUsuario;
    ELSE
        UPDATE Usuario SET Nombre=@Nombre,Email=@Email,IdRol=@IdRol,
            Contrasena=CONVERT(NVARCHAR(256),HASHBYTES('SHA2_256',CAST(@Contrasena AS NVARCHAR(100))),2)
        WHERE IdUsuario=@IdUsuario;
END;
GO

/* ----------------------------------------------------------
   5. CONTROL: filas cargadas en cada tabla
   ---------------------------------------------------------- */
SELECT N'Cliente' AS Tabla, COUNT(*) AS Filas FROM [Cliente]
UNION ALL SELECT N'Consulta' AS Tabla, COUNT(*) AS Filas FROM [Consulta]
UNION ALL SELECT N'Localidad' AS Tabla, COUNT(*) AS Filas FROM [Localidad]
UNION ALL SELECT N'Propietario' AS Tabla, COUNT(*) AS Filas FROM [Propietario]
UNION ALL SELECT N'Rol' AS Tabla, COUNT(*) AS Filas FROM [Rol]
UNION ALL SELECT N'Tipo' AS Tabla, COUNT(*) AS Filas FROM [Tipo]
UNION ALL SELECT N'Propiedad' AS Tabla, COUNT(*) AS Filas FROM [Propiedad]
UNION ALL SELECT N'Usuario' AS Tabla, COUNT(*) AS Filas FROM [Usuario]
UNION ALL SELECT N'Cita' AS Tabla, COUNT(*) AS Filas FROM [Cita]
UNION ALL SELECT N'EcoMarketItem' AS Tabla, COUNT(*) AS Filas FROM [EcoMarketItem]
UNION ALL SELECT N'ImpactoAmbiental' AS Tabla, COUNT(*) AS Filas FROM [ImpactoAmbiental]
UNION ALL SELECT N'MejoraSustentable' AS Tabla, COUNT(*) AS Filas FROM [MejoraSustentable]
UNION ALL SELECT N'Operacion' AS Tabla, COUNT(*) AS Filas FROM [Operacion]
UNION ALL SELECT N'PropiedadImagen' AS Tabla, COUNT(*) AS Filas FROM [PropiedadImagen]
UNION ALL SELECT N'Residuo' AS Tabla, COUNT(*) AS Filas FROM [Residuo]
UNION ALL SELECT N'Comision' AS Tabla, COUNT(*) AS Filas FROM [Comision]
UNION ALL SELECT N'Contrato' AS Tabla, COUNT(*) AS Filas FROM [Contrato]
UNION ALL SELECT N'EcoMarketContacto' AS Tabla, COUNT(*) AS Filas FROM [EcoMarketContacto]
UNION ALL SELECT N'ContratoDocumento' AS Tabla, COUNT(*) AS Filas FROM [ContratoDocumento]
UNION ALL SELECT N'EcoMarketMensaje' AS Tabla, COUNT(*) AS Filas FROM [EcoMarketMensaje]
UNION ALL SELECT N'Pago' AS Tabla, COUNT(*) AS Filas FROM [Pago]
ORDER BY Tabla;
GO
